  function pageAccent(id){const colors=['#b8573b','#246b58','#3f6d9a','#9a7130','#665c8c','#287b83','#8d5840'];let value=0;for(const character of id)value=(value*31+character.charCodeAt(0))|0;return colors[Math.abs(value)%colors.length]}
  const readInputs = () => ({a:$('inputA')?.value??'',b:$('inputB')?.value??'',c:$('inputC')?.value??'',mode:$('mode')?.value??'format'});
