  function formatJs(value,minify=false){if(minify)return value.replace(/\/\*[\s\S]*?\*\//g,'').replace(/(^|[^:])\/\/.*$/gm,'$1').replace(/\s+/g,' ').trim();let out='',depth=0,quote='',escape=false;for(const char of value){if(quote){out+=char;if(escape)escape=false;else if(char==='\\')escape=true;else if(char===quote)quote='';continue}if(char==='"'||char==="'"||char==='`'){quote=char;out+=char}else if(char==='{'){out+=' {\n'+'  '.repeat(++depth)}else if(char==='}'){depth=Math.max(0,depth-1);out=out.trimEnd()+'\n'+'  '.repeat(depth)+'}\n'+'  '.repeat(depth)}else if(char===';')out+=';\n'+'  '.repeat(depth);else out+=char}return out.trim();}
  function cronNext(expression,count=5,timeZone='local'){const fields=expression.trim().split(/\s+/);if(fields.length!==5)throw Error('Use standard 5-field cron: minute hour day month weekday.');const ranges=[[0,59],[0,23],[1,31],[1,12],[0,7]];const parsed=fields.map((field,index)=>{if(!/^[\d*/,-]+$/.test(field))throw Error('Unsupported cron field. Use numbers, *, ranges, lists and steps.');const allowed=new Set();for(const part of field.split(',')){const [range,stepText]=part.split('/');const step=Number(stepText||1);if(!Number.isInteger(step)||step<1)throw Error('Cron step must be a positive integer.');let start,end;if(range==='*'){[start,end]=ranges[index]}else if(range.includes('-'))[start,end]=range.split('-').map(Number);else start=end=Number(range);if(!Number.isInteger(start)||!Number.isInteger(end)||start<ranges[index][0]||end>ranges[index][1]||start>end)throw Error(`Cron value outside allowed range ${ranges[index].join('-')}.`);for(let n=start;n<=end;n+=step)allowed.add(index===4&&n===7?0:n)}return allowed});const formatter=timeZone==='local'?null:new Intl.DateTimeFormat('en-US',{timeZone,minute:'numeric',hour:'numeric',day:'numeric',month:'numeric',weekday:'short',hourCycle:'h23'});const valuesAt=(date)=>{if(!formatter)return[date.getMinutes(),date.getHours(),date.getDate(),date.getMonth()+1,date.getDay()];const parts=Object.fromEntries(formatter.formatToParts(date).map(part=>[part.type,part.value]));return[Number(parts.minute),Number(parts.hour),Number(parts.day),Number(parts.month),['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(parts.weekday)]};const matches=(date)=>{const values=valuesAt(date),dayMatch=parsed[2].has(values[2]),weekdayMatch=parsed[4].has(values[4]),dayWildcard=fields[2]==='*'||fields[2].startsWith('*/'),weekdayWildcard=fields[4]==='*'||fields[4].startsWith('*/');return parsed[0].has(values[0])&&parsed[1].has(values[1])&&parsed[3].has(values[3])&&(dayWildcard||weekdayWildcard?dayMatch&&weekdayMatch:dayMatch||weekdayMatch)};const times=[];let cursor=new Date();cursor.setUTCSeconds(0,0);cursor.setTime(cursor.getTime()+60000);const limit=cursor.getTime()+366*24*60*60*1000;while(cursor.getTime()<limit&&times.length<count){if(matches(cursor))times.push(new Date(cursor));cursor.setTime(cursor.getTime()+60000)}return times;}
  async function processText(tool){const {a,b,mode}=readInputs();switch(tool.id){
    case 'pii':{const hits=scanPii(a);const counts={};hits.forEach(x=>counts[x.type]=(counts[x.type]||0)+1);state.output=JSON.stringify(hits,null,2);setResult(`<div class="status">${hits.length} possible match(es). Pattern matches are clues, not identity verification.</div><table class="result-table"><tbody>${Object.entries(counts).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${v}</td></tr>`).join('')}</tbody></table><pre>${esc(hits.map(x=>`${x.type} · ${x.index+1}: ${x.value}`).join('\n')||'No supported patterns found.')}</pre>`);break}
    case 'privacy-text':{const result=await cleanPrivacy(a);state.output=result.cleaned;setResult(`<div class="status">${result.findings.length} pattern(s) replaced. Check the output before sharing.</div><pre>${esc(result.cleaned)}</pre>`);break}
    case 'json-diff':{let left,right;try{left=JSON.parse(a);right=JSON.parse(b)}catch(error){throw Error(`Invalid JSON: ${error.message}`)}const changes=compareJson(left,right);state.output=JSON.stringify(changes,null,2);setResult(changes.length?`<p>${changes.length} structural change(s)</p><table class="result-table"><thead><tr><th>Type</th><th>Path</th><th>Before / after</th></tr></thead><tbody>${changes.map(x=>`<tr><td>${x.type}</td><td class="mono">${esc(x.path)}</td><td>${esc(x.type==='Changed'?`${JSON.stringify(x.before)} → ${JSON.stringify(x.after)}`:JSON.stringify(x.value))}</td></tr>`).join('')}</tbody></table>`:'<div class="status">JSON values are equal.</div>');break}
    case 'text-diff':{state.output=lineDiff(a,b,mode,$('ignoreCase').checked,$('ignoreWhitespace').checked);setResult(`<pre>${esc(state.output)}</pre>`);break}
    case 'csv-diff':{const left=parseCsv(a),right=parseCsv(b);if(!left.length||!right.length)throw Error('Both CSV inputs need a header row.');const key=$('primaryKey').value.trim();const li=key?left[0].indexOf(key):-1,ri=key?right[0].indexOf(key):-1;if(key&&(li<0||ri<0))throw Error('Primary key must exist in both headers.');const encode=(row)=>JSON.stringify(row);const map=(rows,index)=>new Map(rows.slice(1).map((row,n)=>[index>=0?row[index]:String(n),{row,n:n+2}]));const lm=map(left,li),rm=map(right,ri);const added=[...rm].filter(([k])=>!lm.has(k)),removed=[...lm].filter(([k])=>!rm.has(k)),changed=[];for(const [k,l] of lm)if(rm.has(k)&&encode(l.row)!==encode(rm.get(k).row))changed.push({key:k,before:l.row,after:rm.get(k).row});const summary={added:added.length,removed:removed.length,changed:changed.length,unchanged:Math.max(0,Math.min(lm.size,rm.size)-changed.length)};state.output=JSON.stringify({summary,added:added.map(x=>x[1].row),removed:removed.map(x=>x[1].row),changed},null,2);setResult(`<div class="status">Added ${summary.added} · Removed ${summary.removed} · Changed ${summary.changed} · Unchanged ${summary.unchanged}</div><pre>${esc(state.output)}</pre>`);break}
    case 'api-format':{const input=a.trim();if(!input)throw Error('Paste a response body first.');let output=input;if(mode==='json'||(mode==='auto'&&/^[\[{]/.test(input))){output=JSON.stringify(JSON.parse(input),null,2)}else if(mode==='xml'||(mode==='auto'&&/^</.test(input)))output=xmlFormat(input);else if(mode==='html')output=htmlFormat(input);state.output=output;setResult(`<pre>${esc(output)}</pre>`);break}
    case 'headers':{const lines=a.split(/\r?\n/),headers={},duplicates=[];let status=lines[0]||'';for(const line of lines.slice(1)){const split=line.indexOf(':');if(split<1)continue;const key=line.slice(0,split).trim().toLowerCase(),value=line.slice(split+1).trim();if(headers[key])duplicates.push(key);headers[key]=headers[key]?`${headers[key]}, ${value}`:value}const checks=['content-type','content-length','cache-control','content-security-policy','strict-transport-security','x-content-type-options','referrer-policy','permissions-policy','access-control-allow-origin','server'];const findings=checks.map(key=>[key,headers[key]||'Not present']);state.output=JSON.stringify({status,headers,duplicates},null,2);setResult(`<div class="notice"><strong>Informational analysis, not a penetration test.</strong><span>${duplicates.length?`Duplicate fields: ${esc(duplicates.join(', '))}`:'No duplicate headers observed.'}</span></div><table class="result-table"><tbody>${findings.map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table>`);break}
    case 'url-parser':{let url;try{url=new URL(a)}catch{throw Error('Enter a valid absolute URL including protocol.')}const params=[...url.searchParams.entries()];state.output=JSON.stringify({protocol:url.protocol,host:url.host,hostname:url.hostname,port:url.port,path:url.pathname,query:params,fragment:url.hash,username:url.username,password:url.password,origin:url.origin},null,2);setResult(`<table class="result-table"><tbody>${Object.entries(JSON.parse(state.output)).map(([k,v])=>`<tr><th>${esc(k)}</th><td>${esc(Array.isArray(v)?JSON.stringify(v):v)}</td></tr>`).join('')}</tbody></table>${url.username||url.password?'<div class="status warn">Warning: URL contains embedded credentials.</div>':''}`);break}
    case 'url-builder':{const url=new URL(b||'/',a);for(const line of $('inputC').value.split(/\r?\n/)){const index=line.indexOf('=');if(index>0)url.searchParams.append(line.slice(0,index).trim(),line.slice(index+1).trim())}if($('campaign').value)url.searchParams.set('utm_source',$('campaign').value.trim());if($('fragment').value)url.hash=$('fragment').value;state.output=url.toString();outputText(state.output,'url.txt');break}
    case 'regex':{if(a.length>50000)throw Error('Test text is limited to 50,000 characters.');let regex;try{regex=new RegExp(b,$('flags').value)}catch(error){throw Error(`Invalid regular expression: ${error.message}`)}const matches=[...a.matchAll(regex)].slice(0,1000);state.output=JSON.stringify(matches.map(match=>({match:match[0],index:match.index,groups:match.slice(1)})),null,2);const replaced=a.replace(regex,$('replacement').value);setResult(`<div class="status">${matches.length} match(es) shown (maximum 1,000). Regex runs locally; avoid untrusted catastrophic patterns on large inputs.</div><pre>${esc(state.output)}</pre><h3>Replace result</h3><pre>${esc(replaced)}</pre>`);break}
    case 'cron':{const timeZone=$('timezone').value.trim()||'local',times=cronNext(a,5,timeZone),formatter=new Intl.DateTimeFormat('en-US',{timeZone:timeZone==='local'?undefined:timeZone,dateStyle:'medium',timeStyle:'short'});state.output=times.map(date=>formatter.format(date)).join('\n');setResult(`<div class="status">Valid common 5-field cron. Preview timezone: ${esc(timeZone)}.</div><pre>${esc(state.output||'No run found in the next 366 days.')}</pre>`);break}
    case 'timestamp':{const date=/^-?\d+(\.\d+)?$/.test(a.trim())?new Date(Number(a)*(Math.abs(Number(a))<1e11?1000:1)):new Date(a);if(Number.isNaN(date.getTime()))throw Error('Enter Unix seconds/milliseconds or a supported date string.');const timeZone=$('timezone').value,data={unixSeconds:Math.floor(date.getTime()/1000),unixMilliseconds:date.getTime(),unixMicroseconds:date.getTime()*1000,iso:date.toISOString(),utc:date.toUTCString(),display:date.toLocaleString(undefined,{timeZone:timeZone==='UTC'?'UTC':undefined}),displayTimeZone:timeZone,relativeSeconds:Math.round((date.getTime()-Date.now())/1000)};state.output=JSON.stringify(data,null,2);setResult(`<table class="result-table"><tbody>${Object.entries(data).map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table>`);break}
    case 'sql-format':case 'sql-minify':state.output=sqlFormat(a,tool.id==='sql-minify');outputText(state.output,'formatted.sql');break;
    case 'html-format':state.output=htmlFormat(a,mode==='minify');outputText(state.output,'formatted.html');break;
    case 'css-format':{state.output=formatCss(a,mode==='minify');const vars=[...new Set(a.match(/--[\w-]+(?=\s*:)/g)||[])],selectors=[...(a.match(/([^{}]+)\{/g)||[])].map(x=>x.slice(0,-1).trim()),duplicates=selectors.filter((item,index)=>selectors.indexOf(item)!==index);setResult(`<pre>${esc(state.output)}</pre><p>CSS variables: ${esc(vars.join(', ')||'none found')}</p><p>Repeated selectors: ${esc([...new Set(duplicates)].join(', ')||'none found')}</p>`);break}
    case 'js-format':state.output=formatJs(a,mode==='minify');outputText(state.output,'formatted.js');break;
    case 'markdown':case 'md-html':{const html=markdownToHtml(a);state.output=html;setResult(`<div class="status">Preview text is escaped and rendered without injecting HTML or scripts.</div><div>${markdownPreview(a)}</div><details><summary>Generated HTML</summary><pre>${esc(html)}</pre></details>`);break}
    case 'html-md':state.output=htmlToMarkdown(a);outputText(state.output,'converted.md');break;
    case 'contrast':{const ratio=contrastRatio($('foreground').value,$('background').value),normal=ratio>=4.5,large=ratio>=3;state.output=`Contrast ratio: ${ratio.toFixed(2)}:1`;setResult(`<div class="status ${normal?'':'warn'}">${ratio.toFixed(2)}:1 · Normal text ${normal?'passes':'fails'} WCAG AA · Large text ${large?'passes':'fails'} WCAG AA</div><div style="margin-top:12px;padding:24px;background:${$('background').value};color:${$('foreground').value};font-size:22px">Sample text preview</div>`);break}
    case 'random':randomWork();break;
    default:throw Error('This tool operation is not available yet.');
  }}
  function markdownToHtml(text){return text.split(/\n{2,}/).map(block=>{let line=block.trim();if(/^#{1,6}\s/.test(line)){const n=line.match(/^#+/)[0].length;return `<h${n}>${esc(line.slice(n).trim())}</h${n}>`}if(/^[-*+]\s/.test(line))return `<ul>${line.split('\n').map(item=>`<li>${esc(item.replace(/^[-*+]\s/,''))}</li>`).join('')}</ul>`;if(/^>\s/.test(line))return `<blockquote>${esc(line.replace(/^>\s?/gm,''))}</blockquote>`;return `<p>${esc(line).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>')}</p>`}).join('\n')}
  function markdownPreview(text){return text.split(/\n{2,}/).map(block=>{const line=block.trim();if(/^#{1,6}\s/.test(line)){const n=line.match(/^#+/)[0].length;return `<h${n}>${esc(line.slice(n).trim())}</h${n}>`}if(/^[-*+]\s/.test(line))return `<ul>${line.split('\n').map(x=>`<li>${esc(x.replace(/^[-*+]\s/,''))}</li>`).join('')}</ul>`;return `<p>${esc(line)}</p>`}).join('')}
  function htmlToMarkdown(value){const doc=new DOMParser().parseFromString(value,'text/html');const walk=(node)=>{if(node.nodeType===Node.TEXT_NODE)return node.textContent.trim();if(node.nodeType!==Node.ELEMENT_NODE)return '';const children=[...node.childNodes].map(walk).filter(Boolean).join(node.tagName==='LI'?' ':'');const tag=node.tagName.toLowerCase();if(/^h[1-6]$/.test(tag))return `${'#'.repeat(Number(tag[1]))} ${children}\n\n`;if(tag==='p')return `${children}\n\n`;if(tag==='li')return `- ${children}\n`;if(tag==='a')return `[${children}](${node.getAttribute('href')||''})`;if(tag==='strong'||tag==='b')return `**${children}**`;if(tag==='em'||tag==='i')return `*${children}*`;if(tag==='code')return `\`${children}\``;if(tag==='br')return '\n';if(tag==='blockquote')return `${children.split('\n').map(x=>`> ${x}`).join('\n')}\n\n`;if(tag==='ul'||tag==='ol')return `${children}\n`;return children};return [...doc.body.childNodes].map(walk).join('').trim()}
  function linear(hex){const values=hex.slice(1).match(/.{2}/g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return .2126*values[0]+.7152*values[1]+.0722*values[2]}
  function contrastRatio(a,b){const x=linear(a),y=linear(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}

  async function fileToBase64(file){if(file.size>32*1024*1024)throw Error('For memory safety, Base64 file conversion is limited to 32 MB.');const bytes=new Uint8Array(await file.arrayBuffer());return bytesToBase64(bytes)}
  async function handleBase64(){const mode=$('mode').value,file=$('inputFiles').files[0],input=$('inputA')?.value||'';if(mode==='file-to-base64'){if(!file)throw Error('Choose a file.');const result=await fileToBase64(file);outputText(result,'file.base64');return}if(mode==='base64-to-file'){const bytes=base64ToBytes(input.replace(/^data:[^,]*;base64,/i,'').replace(/\s/g,''));download(new Blob([bytes],{type:'application/octet-stream'}),'decoded-file.bin','application/octet-stream');outputText(`Decoded ${bytes.length} bytes to decoded-file.bin`);return}if(mode==='encode-text'){outputText(bytesToBase64(new TextEncoder().encode(input)),'encoded.txt');return}const normalized=input.replace(/-/g,'+').replace(/_/g,'/');outputText(new TextDecoder('utf-8',{fatal:true}).decode(base64ToBytes(normalized)),'decoded.txt')}
  async function deriveKey(password,salt,usages=['encrypt','decrypt']){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,usages)}
  function reportProgress(percent){const bar=$('progressBar');if(bar)bar.style.width=`${percent}%`}
  async function encryptFiles(files,password){const salt=crypto.getRandomValues(new Uint8Array(16)),key=await deriveKey(password,salt),packageData={format:'ThakronixEncrypted',version:1,algorithm:'AES-GCM-256',kdf:'PBKDF2-SHA-256',iterations:310000,salt:bytesToBase64(salt),files:[]};let total=files.reduce((sum,file)=>sum+file.size,0),done=0;for(const file of files){const chunks=[];for(let offset=0;offset<file.size||(!file.size&&offset===0);offset+=4*1024*1024){const clear=new Uint8Array(await file.slice(offset,Math.min(offset+4*1024*1024,file.size)).arrayBuffer());const iv=crypto.getRandomValues(new Uint8Array(12)),encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,clear);chunks.push({iv:bytesToBase64(iv),data:bytesToBase64(new Uint8Array(encrypted))});done+=clear.length;reportProgress(total?Math.round(done/total*100):100);if(file.size===0)break}const metadataIv=crypto.getRandomValues(new Uint8Array(12)),metadata=await crypto.subtle.encrypt({name:'AES-GCM',iv:metadataIv},key,new TextEncoder().encode(JSON.stringify({name:file.name,type:file.type,size:file.size,lastModified:file.lastModified})));packageData.files.push({metadataIv:bytesToBase64(metadataIv),metadata:bytesToBase64(new Uint8Array(metadata)),chunks})}const packed=new Blob([JSON.stringify(packageData)],{type:'application/vnd.Thakronix.encrypted+json'});return{packed,packageData}}
  async function decryptPackage(file,password){const pkg=JSON.parse(await file.text());if(pkg.format!=='ThakronixEncrypted'||pkg.version!==1||!Array.isArray(pkg.files))throw Error('Unsupported or damaged encrypted package.');const salt=base64ToBytes(pkg.salt),key=await deriveKey(password,salt),outputs=[];let done=0;for(const item of pkg.files){const parts=[];try{for(const chunk of item.chunks){const clear=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(chunk.iv)},key,base64ToBytes(chunk.data));parts.push(clear);done+=clear.byteLength;reportProgress(0)}const metadataClear=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(item.metadataIv)},key,base64ToBytes(item.metadata)),metadata=JSON.parse(new TextDecoder().decode(metadataClear));outputs.push({name:metadata.name,type:metadata.type||'application/octet-stream',blob:new Blob(parts,{type:metadata.type||'application/octet-stream'})})}catch{throw Error('Password incorrect or package integrity check failed. No plaintext file was produced.')}}return outputs}
  async function runEncryption(){const files=[...$('inputFiles').files],password=$('password').value;if(!files.length)throw Error('Choose one or more files.');if(!password)throw Error('Enter the package password.');if($('confirmPassword').checked&&prompt('Confirm the package password:')!==password)throw Error('Password confirmation did not match.');$('runTool').disabled=true;reportProgress(0);try{if($('mode').value==='encrypt'){const {packed,packageData}=await encryptFiles(files,password);const report={algorithm:packageData.algorithm,kdf:packageData.kdf,iterations:packageData.iterations,salt:packageData.salt,fileCount:packageData.files.length,chunkSize:4194304};download(packed,`${files.length===1?'encrypted-file':'files'}.encrypted`,'application/vnd.Thakronix.encrypted+json');const digest=await crypto.subtle.digest('SHA-256',await packed.arrayBuffer()),checksum=[...new Uint8Array(digest)].map(byte=>byte.toString(16).padStart(2,'0')).join('');setResult(`<div class="status">Encrypted package downloaded. Filenames and file metadata are encrypted; AES-GCM authentication verifies metadata and every chunk.</div><pre>${esc(JSON.stringify({...report,sha256:checksum},null,2))}</pre>`)}else{const outputs=[];for(const file of files)outputs.push(...await decryptPackage(file,password));for(const item of outputs)download(item.blob,item.name,item.type);setResult(`<div class="status">Integrity verified; ${outputs.length} file(s) decrypted and downloaded.</div><pre>${esc(outputs.map(x=>x.name).join('\n'))}</pre>`)}}finally{$('runTool').disabled=false}}

  const vaultRequest=(db,store,mode,action)=>new Promise((resolve,reject)=>{const tx=db.transaction(store,mode),request=action(tx.objectStore(store));request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);tx.onabort=()=>reject(tx.error)});
  function openVaultDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('Thakronix-encrypted-vault',1);req.onupgradeneeded=()=>{const db=req.result;db.createObjectStore('meta');db.createObjectStore('items',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
  async function vaultMeta(){return vaultRequest(state.vaultDb,'meta','readonly',store=>store.get('config'))}
  function armVaultTimeout(){clearTimeout(vaultLockTimer);if(state.vaultKey&&state.active==='vault')vaultLockTimer=setTimeout(lockVault,5*60*1000)}
  async function vaultCreate(){const password=$('vaultPassword').value;if(password.length<12)throw Error('Master password must be at least 12 characters.');state.vaultDb=await openVaultDb();if(await vaultMeta())throw Error('Vault already exists. Unlock it instead.');state.vaultSalt=crypto.getRandomValues(new Uint8Array(16));state.vaultKey=await deriveKey(password,state.vaultSalt);const checkIv=crypto.getRandomValues(new Uint8Array(12)),check=await crypto.subtle.encrypt({name:'AES-GCM',iv:checkIv},state.vaultKey,new TextEncoder().encode('Thakronix vault check'));await vaultRequest(state.vaultDb,'meta','readwrite',store=>store.put({salt:bytesToBase64(state.vaultSalt),checkIv:bytesToBase64(checkIv),check:bytesToBase64(new Uint8Array(check)),created:new Date().toISOString()},'config'));await refreshVault();armVaultTimeout();setStatus('Vault created and unlocked. Export an encrypted backup after adding files.')}
  async function vaultUnlock(){const password=$('vaultPassword').value;if(!password)throw Error('Enter the master password.');state.vaultDb=await openVaultDb();const meta=await vaultMeta();if(!meta)throw Error('No vault exists in this browser yet.');state.vaultSalt=base64ToBytes(meta.salt);const key=await deriveKey(password,state.vaultSalt);try{await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(meta.checkIv)},key,base64ToBytes(meta.check))}catch{throw Error('Wrong password or damaged vault.')}state.vaultKey=key;await refreshVault();armVaultTimeout();setStatus('Vault unlocked. Files are decrypted only when downloaded or previewed.')}
